TAB_ExpeditionLevel[1] = {"Bình nguyên Elvan",360,3,"Cuộc sống tưởng chừng bình yên lại ẩn chứa nhiều sóng gió… Xung quanh liên tục xảy ra chuyện kỳ lạ, rốt cuộc là tình cờ hay có người cản trở? Đối mặt với một nơi vừa quen thuộc vừa xa lạ, bạn thầm e ngại. Bạn bình tĩnh ngửi thấy mùi thuốc súng phảng phất và quyết tâm bắt cho bằng được kẻ phá rối này!",1,1,"/map/1.tmx",1,1,10,1,{1701101,1}}
TAB_ExpeditionLevel[2] = {"Bình nguyên Xibia",401,3,"Khi đã giải quyết xong kẻ địch trước mắt, bạn mới phát hiện đó chẳng qua chỉ là tay sai bị người khác khống chế. Còn kẻ thù thật sự thì đang ở xa tận bên kia bờ! Lúc này, có tin kẻ thù đang có âm mưu khổng lồ trong khi bạn đang chiến đấu. Bạn không thể không bước chân vào hành trình mạo hiểm.",2,2,"/map/2.tmx",2,2,11,2,{1701102,1}}
TAB_ExpeditionLevel[3] = {"Bãi biển Rea",431,3,"Vì kẻ địch cản trở khiến máy bay bị rơi, mất đi phương tiện đi lại nên bạn đành phải đáp xuống vùng đất mới. Tâm trạng căng thẳng sau khi trải qua một trận chiến dần bình tĩnh lại. Bãi cát, người đẹp, bóng chuyền! Giờ bạn muốn nghỉ dưỡng ở bãi biển xinh đẹp này. Nhưng lại không biết rằng móng vuốt của kẻ thù đã theo bạn đến đây...",3,3,"/map/3.tmx",3,3,12,2,{1701103,1}}
TAB_ExpeditionLevel[4] = {"Bãi biển Ares",461,3,"Tiện tay giải quyết kẻ thù ngáng đường, bạn biết rằng không còn nhiều thời gian cho đến khi quyết đấu. Nhưng đến một nơi xa lạ, bạn hiểu rõ rằng kẻ thù sẽ mai phục sẵn trên đường bạn cần đi qua. Chỉ có điều muốn tìm thấy kẻ thù thì cần thêm thời gian, bạn quyết định ôm cây đợi thỏ chờ kẻ thù tìm đến.",4,4,"/map/4.tmx",4,4,13,3,{1701104,1}}
TAB_ExpeditionLevel[5] = {"Cồn Cát Hatta",491,3,"Cuối cùng cũng đến được căn cứ địch, nhìn lại quá khứ, nước mắt lưng tròng. Cát vàng không thể ngăn cản trái tim nhiệt tình của ngươi! Đột nhiên, một tiếng kêu cứu từ xa vang lên, ngươi không thể phân biệt được đâu là hung thủ hay chỉ là cái bẫy? Bây giờ, hãy tìm kẻ thù và đánh bại hắn!",5,5,"/map/5.tmx",5,5,14,3,{1701105,1}}
TAB_ExpeditionLevel[6] = {"Cồn Cát Leo",516,3,"Sau một trận đánh ác liệt, đã đến được căn cứ địch, phát hiện ra nơi này chỉ là 1 cái vỏ bên ngoài, còn kẻ địch vẫn không có tung tích. Ngay khi hết cách, đồng hành đã chỉ cho bạn một hướng đi. Hóa ra đây mới là trung tâm của tội phạm ngầm! Các dũng sĩ, tiến lên nào!",6,6,"/map/7.tmx",6,6,15,4,{1701106,1}}
